//! Reading a plain Frame axis value from text, checked against the C
//! library.
//!
//! `axis_unformat_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/axis_unformat_probe.c`. C's `AxisUnformat`
//! (axis.c:1335) reads the value with `sscanf( "%lf %n" )`, which takes the
//! longest prefix `strtod` accepts, hexadecimal floats, infinities and NaNs
//! included, and counts the white space around it; otherwise it accepts the
//! `<bad>` token. The corpus was captured on macOS; the probe names the
//! cases where C libraries differ.

#[path = "axis_unformat_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{BasicFrameBuilder, Frame};

/// Equal values, telling -0 from 0 and treating every NaN as equal.
fn same(a: f64, b: f64) -> bool {
    (a.is_nan() && b.is_nan()) || a.to_bits() == b.to_bits()
}

#[test]
fn unformat_matches_the_c_library() {
    let f = BasicFrameBuilder::new(1).build().unwrap();
    let mut failures = Vec::new();
    for &(text, nread, value) in cases::CASES {
        let (got, n) = f.unformat(1, text).unwrap();
        if n != nread || !same(got, value) {
            failures.push(format!(
                "{text:?}: got ({got:?}, {n}), C gives ({value:?}, {nread})"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
